// Google Maps URLs preserve waypoint order. Mobile browsers support up to 3
// intermediate waypoints; other supported clients support up to 9.
export function stopPoint(stop){return {value:stop.location?`${stop.location.lat},${stop.location.lng}`:`${stop.network} ${stop.name.replaceAll('·','')} İzmir Yönü`,id:stop.location?stop.id:undefined,label:stop.name};}
export function directionsURL(points){if(points.length<2)throw Error('A route needs an origin and destination.');if(points.length>11)throw Error('Google Maps supports at most 9 intermediate stops in one link.');const u=new URL('https://www.google.com/maps/dir/');u.searchParams.set('api','1');u.searchParams.set('travelmode','driving');u.searchParams.set('origin',points[0].value);u.searchParams.set('destination',points.at(-1).value);if(points[0].id)u.searchParams.set('origin_place_id',points[0].id);if(points.at(-1).id)u.searchParams.set('destination_place_id',points.at(-1).id);const via=points.slice(1,-1);if(via.length){u.searchParams.set('waypoints',via.map(p=>p.value).join('|'));if(via.every(p=>p.id))u.searchParams.set('waypoint_place_ids',via.map(p=>p.id).join('|'));}if(u.href.length>2048)throw Error('Route link exceeds Google’s URL length limit.');return u.href;}
export function exportTrip(origin,destination,stops){const points=[{value:origin,label:origin},...stops.map(stopPoint),{value:destination,label:destination}];let full=null;try{full=directionsURL(points);}catch{}const parts=[];let start=0;while(start<points.length-1){let end=Math.min(start+4,points.length-1),url;while(end>start){try{url=directionsURL(points.slice(start,end+1));break;}catch{end--;}}if(!url)throw Error('An address is too long to export. Shorten it and calculate again.');parts.push({url,from:points[start].label,to:points[end].label,stopLabels:points.slice(start+1,end+1).map(p=>p.label)});start=end;}return {full,parts,count:stops.length};}
